
SELECT F0_0.PROV_SUPPLIER_S__SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY, F0_0.PROV_NATION_N__NATIONKEY AS PROV_NATION_N__NATIONKEY, F0_0.PROV_PARTSUPP_PS__PARTKEY AS PROV_PARTSUPP_PS__PARTKEY, F0_0.PROV_PART_P__PARTKEY AS PROV_PART_P__PARTKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.S_NAME AS S_NAME, F0_0.S_ADDRESS AS S_ADDRESS
FROM (
SELECT F0_0.S_NAME AS S_NAME, F0_0.S_ADDRESS AS S_ADDRESS, F0_0.PROV_SUPPLIER_S__SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY, F0_0.PROV_NATION_N__NATIONKEY AS PROV_NATION_N__NATIONKEY, F0_0.PROV_PARTSUPP_PS__PARTKEY AS PROV_PARTSUPP_PS__PARTKEY, F0_0.PROV_PART_P__PARTKEY AS PROV_PART_P__PARTKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY
FROM (
SELECT F0_0.S_SUPPKEY AS S_SUPPKEY, F0_0.S_NAME AS S_NAME, F0_0.S_ADDRESS AS S_ADDRESS, F0_0.S_NATIONKEY AS S_NATIONKEY, F0_0.N_NATIONKEY AS N_NATIONKEY, F0_0.N_NAME AS N_NAME, F1_0.PS_SUPPKEY AS PS_SUPPKEY, F0_0.PROV_SUPPLIER_S__SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY, F0_0.PROV_NATION_N__NATIONKEY AS PROV_NATION_N__NATIONKEY, F1_0.PROV_PARTSUPP_PS__PARTKEY AS PROV_PARTSUPP_PS__PARTKEY, F1_0.PROV_PART_P__PARTKEY AS PROV_PART_P__PARTKEY, F1_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY
FROM ((
SELECT F0_0.S_SUPPKEY AS S_SUPPKEY, F0_0.S_NAME AS S_NAME, F0_0.S_ADDRESS AS S_ADDRESS, F0_0.S_NATIONKEY AS S_NATIONKEY, F1_0.N_NATIONKEY AS N_NATIONKEY, F1_0.N_NAME AS N_NAME, F0_0.PROV_SUPPLIER_S__SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY, F1_0.PROV_NATION_N__NATIONKEY AS PROV_NATION_N__NATIONKEY
FROM ((
SELECT F0_0.S_SUPPKEY AS S_SUPPKEY, F0_0.S_NAME AS S_NAME, F0_0.S_ADDRESS AS S_ADDRESS, F0_0.S_NATIONKEY AS S_NATIONKEY, F0_0.S_SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY
FROM SUPPLIER F0_0) F0_0 CROSS JOIN (
SELECT F0_0.N_NATIONKEY AS N_NATIONKEY, F0_0.N_NAME AS N_NAME, F0_0.N_NATIONKEY AS PROV_NATION_N__NATIONKEY
FROM NATION F0_0) F1_0)) F0_0 CROSS JOIN (
SELECT F0_0.PS_SUPPKEY AS PS_SUPPKEY, F0_0.PROV_PARTSUPP_PS__PARTKEY AS PROV_PARTSUPP_PS__PARTKEY, F0_0.PROV_PART_P__PARTKEY AS PROV_PART_P__PARTKEY, F1_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY
FROM ((
SELECT F0_0.PS_PARTKEY AS PS_PARTKEY, F0_0.PS_SUPPKEY AS PS_SUPPKEY, F0_0.PS_AVAILQTY AS PS_AVAILQTY, F0_0.PROV_PARTSUPP_PS__PARTKEY AS PROV_PARTSUPP_PS__PARTKEY, F1_0.PROV_PART_P__PARTKEY AS PROV_PART_P__PARTKEY
FROM ((
SELECT F0_0.PS_PARTKEY AS PS_PARTKEY, F0_0.PS_SUPPKEY AS PS_SUPPKEY, F0_0.PS_AVAILQTY AS PS_AVAILQTY, F0_0.PS_PARTKEY AS PROV_PARTSUPP_PS__PARTKEY
FROM PARTSUPP F0_0) F0_0 JOIN (
SELECT F0_0.P_PARTKEY AS P_PARTKEY, F0_0.PROV_PART_P__PARTKEY AS PROV_PART_P__PARTKEY
FROM (
SELECT F0_0.P_PARTKEY AS P_PARTKEY, F0_0.P_NAME AS P_NAME, F0_0.P_PARTKEY AS PROV_PART_P__PARTKEY
FROM PART F0_0) F0_0
WHERE (F0_0.P_NAME LIKE 'forest%')) F1_0 ON ((F1_0.P_PARTKEY = F0_0.PS_PARTKEY)))) F0_0 JOIN (
SELECT (0.500000 * SUM(F0_0.L_QUANTITY) OVER (PARTITION BY F0_0.L_PARTKEY, F0_0.L_SUPPKEY)) AS COMPUTED, F0_0.L_PARTKEY AS L_PARTKEY, F0_0.L_SUPPKEY AS L_SUPPKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY
FROM (
SELECT F0_0.L_PARTKEY AS L_PARTKEY, F0_0.L_SUPPKEY AS L_SUPPKEY, F0_0.L_QUANTITY AS L_QUANTITY, F0_0.L_SHIPDATE AS L_SHIPDATE, F0_0.L_ORDERKEY AS PROV_LINEITEM_L__ORDERKEY
FROM LINEITEM F0_0) F0_0
WHERE ((F0_0.L_SHIPDATE >= '1994-01-01') AND (F0_0.L_SHIPDATE < '1995-01-01'))) F1_0 ON ((((F0_0.PS_PARTKEY = F1_0.L_PARTKEY) AND (F0_0.PS_SUPPKEY = F1_0.L_SUPPKEY)) AND (F0_0.PS_AVAILQTY > F1_0.COMPUTED))))) F1_0)) F0_0
WHERE (((F0_0.PS_SUPPKEY = F0_0.S_SUPPKEY) AND (F0_0.S_NATIONKEY = F0_0.N_NATIONKEY)) AND (F0_0.N_NAME = 'CANADA'))
ORDER BY S_NAME ASC NULLS LAST) F0_0;


